questionvariables.text:
/* helpers: relation tokens, display strings, inequality builders */
relt(r) := if r="lt" then "\\lt" else if r="le" then "\\le" else if r="gt" then "\\gt" else "\\ge";
reluc(r) := if r="lt" then "<" else if r="le" then "≤" else if r="gt" then ">" else "≥";
relflip(r) := if r="lt" then "gt" else if r="le" then "ge" else if r="gt" then "lt" else "le";
relother(r) := if r="lt" then "le" else if r="le" then "lt" else if r="gt" then "ge" else "gt";
relcomp(r) := if r="lt" then "ge" else if r="le" then "gt" else if r="gt" then "le" else "lt";
strictp(r) := is(r="lt" or r="gt");
/* Typed answers must be one inequality; "and"/"or" statements are rejected at validation. */
vsingle(ex) := if not atom(ex) and member(op(ex), ["and", "or", "nounand", "nounor"]) then "Type a single inequality, without the words and or or." else "";
mkin(u, r, w) := if r="lt" then u<w else if r="le" then u<=w else if r="gt" then u>w else u>=w;
holds(u, r, w) := if r="lt" then is(u<w) else if r="le" then is(u<=w) else if r="gt" then is(u>w) else is(u>=w);
relopts(c) := [["lt",is(c="lt"),"<"],["le",is(c="le"),"≤"],["gt",is(c="gt"),">"],["ge",is(c="ge"),"≥"]];
termp(v) := block([dd], dd: denom(v), while is(mod(dd,2)=0) do dd: dd/2, while is(mod(dd,5)=0) do dd: dd/5, is(dd=1));
nd(v) := if integerp(v) then string(v) else if termp(v) then string(float(v))
  else sconcat(if is(v<0) then "-" else "", "\\frac{", string(abs(num(v))), "}{", string(denom(v)), "}");
ndm(v) := sconcat("\\(", nd(v), "\\)");
/* plain-text number for aria-labels (nd gives TeX fractions, which a screen reader reads raw) */
ndt(v) := if integerp(v) then string(v) else if termp(v) then string(float(v)) else sconcat(string(num(v)), "/", string(denom(v)));
trm(k, v, fst) := block([m, s], m: abs(k), s: if v="" then nd(m) else if m=1 then v else sconcat(nd(m), v),
  if fst then (if k<0 then sconcat("-", s) else s) else (if k<0 then sconcat(" - ", s) else sconcat(" + ", s)));
lfs(L) := block([s, t], s: "", for t in L do (if t[1]#0 then s: sconcat(s, trm(t[1], t[2], is(s="")))), if s="" then "0" else s);
ins(a, b, c, r) := sconcat(lfs([[a,"x"],[b,"y"]]), " ", relt(r), " ", nd(c));
ineqd(a, b, c, r) := sconcat("\\(", ins(a, b, c, r), "\\)");
lind(a, b, c) := sconcat("\\(", lfs([[a,"x"],[b,"y"]]), " = ", nd(c), "\\)");
ineqm(a, b, c, r) := mkin(a*x+b*y, r, c);
/* region helpers: corners of the triangle cut out by three lines, centroid */
meet(L1, L2) := block([d], d: L1[1]*L2[2]-L2[1]*L1[2], [(L1[3]*L2[2]-L2[3]*L1[2])/d, (L1[1]*L2[3]-L2[1]*L1[3])/d]);
ptd(P) := sconcat("(", ndt(P[1]), ", ", ndt(P[2]), ")");
/* system helpers */
spl(L) := sconcat(lfs([[L[1],"x"],[L[2],"y"]]), " = ", ndt(L[3]), if strictp(L[4]) then " (dashed)" else " (solid)");
lkind(L) := if is(L[2]=0) then "vertical" else if is(L[1]=0) then "horizontal" else "sloping";
/* guard test input: the wrong letter(s) for a line */
gk(L) := if is(L[2]=0) then mkin(y, L[4], L[3]) else if is(L[1]=0) then mkin(x, L[4], L[3]) else mkin(L[1]*x, L[4], L[3]);
/* Design: three inequalities that define a region. Source: adapted from SMP GCSE Higher 2, Chapter 1, question D7.
   q52 [[a,b,c,rel] for lines 1, 2, 3]: R is the clear triangle; the sloping line's number varies;
   at least one solid and one dashed line in each entry. */
q52: [[[0,1,-1,"gt"],[1,0,1,"ge"],[8,3,24,"le"]],[[0,1,1,"gt"],[7,8,56,"lt"],[1,0,-2,"ge"]],[[1,0,0,"gt"],[7,4,28,"lt"],[0,1,0,"ge"]],[[0,1,2,"le"],[-7,5,-35,"ge"],[1,0,4,"gt"]],[[0,1,0,"gt"],[1,8,8,"lt"],[1,0,-2,"ge"]],[[1,0,4,"gt"],[-5,6,-30,"ge"],[0,1,1,"le"]],[[1,6,-6,"le"],[1,0,0,"gt"],[0,1,-2,"gt"]],[[0,1,5,"le"],[1,0,5,"le"],[8,7,56,"gt"]],[[7,5,35,"gt"],[0,1,6,"le"],[1,0,6,"lt"]],[[1,0,0,"gt"],[0,1,3,"ge"],[6,5,30,"lt"]]];
ix: 1+rand(10);
S: q52[ix];
ta: makelist(ineqm(S[j][1], S[j][2], S[j][3], S[j][4]), j, 1, 3);
tc: makelist(ineqm(S[j][1], S[j][2], S[j][3], relcomp(S[j][4])), j, 1, 3);
tf: makelist(ineqm(S[j][1], S[j][2], S[j][3], relflip(S[j][4])), j, 1, 3);
ts: makelist(ineqm(S[j][1], S[j][2], S[j][3], relother(S[j][4])), j, 1, 3);
tg: makelist(ineqm(S[j][1], S[j][2], S[j][3]+1, S[j][4]), j, 1, 3);
tgd: makelist(gk(S[j]), j, 1, 3);
ta1: ta[1]; ta2: ta[2]; ta3: ta[3];
teq: S[2][1]*x+S[2][2]*y=S[2][3];
V: [meet(S[2], S[3]), meet(S[1], S[3]), meet(S[1], S[2])];
G: [(V[1][1]+V[2][1]+V[3][1])/3, (V[1][2]+V[2][2]+V[3][2])/3];
ds: makelist(ineqd(S[j][1], S[j][2], S[j][3], S[j][4]), j, 1, 3);
arl: sconcat("A grid from -3 to 10. Line 1: ", spl(S[1]), ". Line 2: ", spl(S[2]), ". Line 3: ", spl(S[3]),
  ". The unwanted side of each line is shaded. R is the clear triangle with corners ", ptd(V[1]), ", ", ptd(V[2]), " and ", ptd(V[3]), ".");

feedbackvariables.text:
/* guard: same letters as the teacher's answer (AlgEquiv ignores the name of a lone variable) */
gsd1: ev(lhs(ans1)-rhs(ans1),simp);
gsv1: sort(listofvars(gsd1));
gtv1: sort(listofvars(ev(lhs(ta[1])-rhs(ta[1]),simp)));
samevars1: is(gsv1 = gtv1);
lok1: polynomialp(gsd1, [x, y]);
lca1: if lok1 then coeff(expand(gsd1), x) else 0;
lcb1: if lok1 then coeff(expand(gsd1), y) else 0;
lc01: if lok1 then ev(expand(gsd1), x=0, y=0) else 0;
llin1: is(lok1 and numberp(lca1) and numberp(lcb1) and numberp(lc01) and not is(lca1=0 and lcb1=0) and is(expand(gsd1-lca1*x-lcb1*y-lc01)=0));
lbd1: if not llin1 then "" else if is(lcb1=0) then sconcat("the vertical line \\(x = ", nd(-lc01/lca1), "\\)")
  else if is(lca1=0) then sconcat("the horizontal line \\(y = ", nd(-lc01/lcb1), "\\)")
  else if is(lc01=0) then "a sloping line through \\((0, 0)\\)"
  else sconcat("a sloping line that crosses the axes at \\((", nd(-lc01/lca1), ", 0)\\) and \\((0, ", nd(-lc01/lcb1), ")\\)");

/* guard: same letters as the teacher's answer (AlgEquiv ignores the name of a lone variable) */
gsd2: ev(lhs(ans2)-rhs(ans2),simp);
gsv2: sort(listofvars(gsd2));
gtv2: sort(listofvars(ev(lhs(ta[2])-rhs(ta[2]),simp)));
samevars2: is(gsv2 = gtv2);
lok2: polynomialp(gsd2, [x, y]);
lca2: if lok2 then coeff(expand(gsd2), x) else 0;
lcb2: if lok2 then coeff(expand(gsd2), y) else 0;
lc02: if lok2 then ev(expand(gsd2), x=0, y=0) else 0;
llin2: is(lok2 and numberp(lca2) and numberp(lcb2) and numberp(lc02) and not is(lca2=0 and lcb2=0) and is(expand(gsd2-lca2*x-lcb2*y-lc02)=0));
lbd2: if not llin2 then "" else if is(lcb2=0) then sconcat("the vertical line \\(x = ", nd(-lc02/lca2), "\\)")
  else if is(lca2=0) then sconcat("the horizontal line \\(y = ", nd(-lc02/lcb2), "\\)")
  else if is(lc02=0) then "a sloping line through \\((0, 0)\\)"
  else sconcat("a sloping line that crosses the axes at \\((", nd(-lc02/lca2), ", 0)\\) and \\((0, ", nd(-lc02/lcb2), ")\\)");

/* guard: same letters as the teacher's answer (AlgEquiv ignores the name of a lone variable) */
gsd3: ev(lhs(ans3)-rhs(ans3),simp);
gsv3: sort(listofvars(gsd3));
gtv3: sort(listofvars(ev(lhs(ta[3])-rhs(ta[3]),simp)));
samevars3: is(gsv3 = gtv3);
lok3: polynomialp(gsd3, [x, y]);
lca3: if lok3 then coeff(expand(gsd3), x) else 0;
lcb3: if lok3 then coeff(expand(gsd3), y) else 0;
lc03: if lok3 then ev(expand(gsd3), x=0, y=0) else 0;
llin3: is(lok3 and numberp(lca3) and numberp(lcb3) and numberp(lc03) and not is(lca3=0 and lcb3=0) and is(expand(gsd3-lca3*x-lcb3*y-lc03)=0));
lbd3: if not llin3 then "" else if is(lcb3=0) then sconcat("the vertical line \\(x = ", nd(-lc03/lca3), "\\)")
  else if is(lca3=0) then sconcat("the horizontal line \\(y = ", nd(-lc03/lcb3), "\\)")
  else if is(lc03=0) then "a sloping line through \\((0, 0)\\)"
  else sconcat("a sloping line that crosses the axes at \\((", nd(-lc03/lca3), ", 0)\\) and \\((0, ", nd(-lc03/lcb3), ")\\)");
